/* ─── URL builders — single source of truth ──────────────────
 * Every URL on the site is generated by these functions.
 * ──────────────────────────────────────────────────────────── */

// ── Service routes ───────────────────────────────────────
const SERVICE_BASE = '/plumbing-services';

export function serviceHub() {
  return `${SERVICE_BASE}/`;
}

export function servicePage(serviceSlug: string) {
  return `${SERVICE_BASE}/${serviceSlug}/`;
}

export function emergencyHub() {
  return '/emergency-plumbing/';
}

// ── Location routes ──────────────────────────────────────
const LOCATION_BASE = '/locations';

export function locationHub() {
  return `${LOCATION_BASE}/`;
}

export function statePage(stateSlug: string) {
  return `${LOCATION_BASE}/${stateSlug}/`;
}

export function cityPage(stateSlug: string, citySlug: string) {
  return `${LOCATION_BASE}/${stateSlug}/${citySlug}/`;
}

export function cityServicePage(
  stateSlug: string,
  citySlug: string,
  serviceSlug: string,
) {
  return `${LOCATION_BASE}/${stateSlug}/${citySlug}/${serviceSlug}/`;
}

// ── Resource / guide routes ──────────────────────────────
const RESOURCE_BASE = '/resources';

export function resourceHub() {
  return `${RESOURCE_BASE}/`;
}

export function guidePage(guideSlug: string) {
  return `${RESOURCE_BASE}/${guideSlug}/`;
}

// ── Static pages ─────────────────────────────────────────
export function homePage() {
  return '/';
}
export function aboutPage() {
  return '/about/';
}
export function contactPage() {
  return '/contact/';
}
export function faqPage() {
  return '/faq/';
}
export function requestServicePage() {
  return '/request-service/';
}
export function privacyPage() {
  return '/privacy/';
}
export function termsPage() {
  return '/terms/';
}
export function accessibilityPage() {
  return '/accessibility/';
}
export function thankYouPage() {
  return '/thank-you/';
}

// ── PPC landing pages ────────────────────────────────────
export function lpPage(slug: string) {
  return `/lp/${slug}/`;
}
